      const terapeuta = tx(d['terapeuta_' + i]);
      if (!terapeuta) { motivos.push('SIN_TERAPEUTA_' + i); continue; }
      items.push({ ...d, tipo_cita_recreada: 'masaje', pabau_base: config.masaje, employee_id: terapeuta, servicio_terapeuta_id: tx(d.service_terapeuta_id), start_time: inicioMasaje });
    }
  }
}

if (motivos.length || !items.length) {
  return [{ json: { ...d, citas_recreadas_ok: false, motivo_recreacion: motivos.join(',') || 'SIN_CITAS_A_RECREAR', citas_a_recrear: 0, items_recreacion: [] } }];
}
return [{ json: { ...d, citas_recreadas_ok: null, motivo_recreacion: null, citas_a_recrear: items.length, items_recreacion: items } }];

// Convierte la lista calculada en items para el nodo HTTP de Pabau.
const d = $input.first().json || {};
const items = Array.isArray(d.items_recreacion) ? d.items_recreacion : [];
if (!items.length) return [{ json: { ...d, citas_recreadas_ok: false, motivo_recreacion: d.motivo_recreacion || 'SIN_CITAS_A_RECREAR' } }];
return items.map(item => ({ json: item, pairedItem: { item: 0 } }));

const entrada = $('Preparar recreacion de citas liberadas').first().json || {};
const esperadas = Number(entrada.citas_a_recrear || 0);
const origen = $('Separar citas por recrear').all().map(i => i.json || {});
const respuestas = $input.all().map((item, k) => {
  const idx = (item.pairedItem && !Array.isArray(item.pairedItem)) ? item.pairedItem.item : k;
  return { r: item.json || {}, src: origen[(idx >= 0 && idx < origen.length) ? idx : k] || {} };
});

function idCita(r) {
  const b = r.body ?? r;
  const id = b.appointment_id ?? b.data?.appointment_id ?? b.data?.appointment?.id ?? b.appointment?.id ?? b.data?.id ?? b.id;
  return /^[1-9]\d*$/.test(String(id ?? '')) ? String(id) : null;
}
function exitosa(r) {
  const b = r.body ?? r;
  return !r.error && Number(r.statusCode) >= 200 && Number(r.statusCode) < 300 && b.success !== false && b.status !== 'error' && !!idCita(r);
}

const aguas = [];
const masajes = [];
const fallidas = [];
respuestas.forEach(({ r, src }) => {
  if (!exitosa(r)) { fallidas.push(String(r.error?.message || r.body?.message || r.statusCode || 'ERROR')); return; }
  const id = idCita(r);
  const tipo = String(src.tipo_cita_recreada ?? r.tipo_cita_recreada ?? '');
  if (tipo === 'agua') aguas.push(id); else masajes.push(id);
});

const personas = Number(entrada.numero_personas ?? entrada.personas ?? entrada.terapeutas_necesarios);
const ok = !fallidas.length && respuestas.length === esperadas && esperadas > 0
  && masajes.length === personas && new Set([...aguas, ...masajes]).size === aguas.length + masajes.length
  && (!entrada.service_agua_id || aguas.length === Number(entrada.jacuzzis_necesarios || 1));

return [{ json: {
  ...entrada,
  citas_recreadas_ok: ok,
  motivo_recreacion: ok ? null : ('RECREACION_INCOMPLETA_' + fallidas.join('|')).slice(0, 240),
  pabau_citas_agua_ids: ok ? aguas : (entrada.pabau_citas_agua_ids ?? []),
  pabau_citas_masaje_ids: ok ? masajes : (entrada.pabau_citas_masaje_ids ?? []),
  pabau_reservado: ok ? true : entrada.pabau_reservado,
  retencion_pabau_at: entrada.retencion_pabau_at ?? new Date().toISOString(),
  total_citas_recreadas: aguas.length + masajes.length
} }];

const anteriores = $('Validar citas recreadas').first().json || {};
const r = $input.first().json || {};
let b = r.body ?? r;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch { b = {}; } }
const codigo = Number(r.statusCode ?? (r.error ? 0 : 200));
const ok = !r.error && codigo >= 200 && codigo < 300 && !(b && b.error) && anteriores.citas_recreadas_ok === true;
const detalle = String(r.error?.description || r.error?.message || (b && b.error && b.error.message) || 'RESPUESTA_NO_ACEPTADA');
return [{ json: {
  ...anteriores,
  guardado_citas_recreadas: ok,
  error_guardado_citas: ok ? null : detalle.slice(0, 200),
} }];
